window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-9ea5d7b8790b654d"]={"versions": [{"id": "FIG-9ea5d7b8790b654d", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Blockdiagramm stellt die AUTOSAR-Schichtenarchitektur für die FlexRay-Kommunikation in der Classic Platform dar. Es ordnet die beteiligten Basissoftware-Module (BSW) vertikal den AUTOSAR-Standardschichten zu:</p>\n<ul class=\"fig-list\">\n<li><strong>System Services</strong> (links angeordnet): Beinhaltet systemweite Dienste mit Bezug zur Kommunikation.</li>\n<li><strong>Communication Services</strong>: Umfasst die protokollunabhängigen und protokollspezifischen Kommunikationsdienste.</li>\n<li><strong>Communication Hardware Abstraction</strong>: Kapselt Hardwareeigenschaften der FlexRay-Controller.</li>\n<li><strong>Communication Drivers</strong>: Beinhaltet hardwarenahe Gerätetreiber.</li>\n<li><strong>µC / Hardware</strong>: Bildet die physischen Ausführungseinheiten (Mikrocontroller und externer Controller) ab.</li>\n</ul>\n<p class=\"fig-p\">Der Fokus liegt auf der Verortung des FlexRay Transportprotokolls (FrTp) innerhalb der Communication Services zwischen dem PDU Router und der Hardware-Abstraktionsschicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Module und Schichtbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>System Services</strong>: Enthält den <code>Ext. Time Service</code> (External Time Service).</li>\n<li><strong>Communication Services</strong>:</li>\n<li><code>Signal GW</code> (Signal Gateway)</li>\n<li><code>AUTOSAR COM</code></li>\n<li><code>DCM Diagnostic Com. Manager</code></li>\n<li><code>Generic NM</code> (Generic Network Management)</li>\n<li><code>XCP Transport Protocol on FlexRay</code> (durchgängig vertikal über die Communication Services angeordnet)</li>\n<li><code>PDU Router</code> (liegt unterhalb von <code>AUTOSAR COM</code> und <code>DCM Diagnostic Com. Manager</code>)</li>\n<li><code>FlexRay Transport Protocol</code> (FrTp, unterhalb des <code>PDU Router</code> platziert)</li>\n<li><code>FlexRay NM</code> (FlexRay Network Management, unterhalb von <code>Generic NM</code>)</li>\n<li><strong>Communication Hardware Abstraction</strong>:</li>\n<li><code>FlexRay Interface</code> (FrIf, bindet <code>PDU Router</code>, <code>FlexRay Transport Protocol</code>, <code>FlexRay NM</code> und <code>XCP Transport Protocol on FlexRay</code> nach unten an)</li>\n<li><code>Driver for external FlexRay Controller</code> (überspannt vertikal sowohl die Hardware-Abstraktions- als auch die Treiberschicht zur Anbindung eines externen Controllers)</li>\n<li><strong>Communication Drivers</strong>:</li>\n<li><code>Driver for internal FlexRay Controller</code> (hardwarenaher Treiber für On-Chip-Peripherie)</li>\n<li><strong>µC / Hardware Layer</strong>:</li>\n<li>Mikrocontroller (<code>µC</code>) mit integriertem <code>FlexRay</code>-Controller</li>\n<li><code>External FlexRay Controller</code> (außerhalb des µC angebunden über den externen Controller-Treiber)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht statische Schichtenbeziehungen und Signal-/PDU-Datenflüsse:</p>\n<ul class=\"fig-list\">\n<li>Signale und Botschaften gelangen aus den oberen Ebenen über <code>AUTOSAR COM</code> oder <code>DCM</code> an den <code>PDU Router</code>.</li>\n<li>Unsegmentierte I-PDUs leitet der <code>PDU Router</code> direkt an das <code>FlexRay Interface</code> weiter.</li>\n<li>Zu segmentierende Datenpakete (I-PDUs größer als eine FlexRay-L-PDU) übergibt der <code>PDU Router</code> an das <code>FlexRay Transport Protocol</code> zur Segmentierung; in Empfangsrichtung erfolgt dort das Reassembly zur Übergabe an den <code>PDU Router</code>.</li>\n<li>Das <code>FlexRay Interface</code> bündelt die L-PDUs aus <code>PDU Router</code>, <code>FlexRay Transport Protocol</code>, <code>FlexRay NM</code> sowie <code>XCP Transport Protocol on FlexRay</code> und reicht sie an den <code>Driver for internal FlexRay Controller</code> bzw. den <code>Driver for external FlexRay Controller</code> weiter.</li>\n<li>Das Netzwerkmanagement interagiert über <code>Generic NM</code> und <code>FlexRay NM</code> mit dem <code>FlexRay Interface</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Entwickler und Integratoren des FlexRay Transport Protocol (FrTp) sind folgende Aspekte normativ relevant:</p>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen</strong>: FrTp muss die standardisierten oberen Schnittstellen zum <code>PDU Router</code> (PduR) sowie die unteren Schnittstellen zum <code>FlexRay Interface</code> (FrIf) implementieren.</li>\n<li><strong>Segmentierung / Reassembly</strong>: FrTp übernimmt ausschließlich den PDU-Transport größerer Nutzlasten; Standardnachrichten können das FrTp umgehen und direkt vom PDU Router zum FlexRay Interface fließen.</li>\n<li><strong>Hardware-Unabhängigkeit</strong>: FrTp interagiert niemals direkt mit den Controllertreibern (<code>Driver for internal FlexRay Controller</code> oder <code>Driver for external FlexRay Controller</code>), sondern ausschließlich abstrahiert über das <code>FlexRay Interface</code>.</li>\n<li><strong>Koexistenz</strong>: FrTp koexistiert in der Communication-Services-Schicht neben parallelen Pfaden wie <code>FlexRay NM</code> und <code>XCP Transport Protocol on FlexRay</code>.</li>\n</ul>"}, {"id": "FIG-6a8393b5358e2932", "releases": ["R4.1.3", "R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Blockdiagramm stellt die AUTOSAR-Schichtenarchitektur für die FlexRay-Kommunikation in der Classic Platform dar. Es ordnet die beteiligten Basissoftware-Module (BSW) vertikal den AUTOSAR-Standardschichten zu:</p>\n<ul class=\"fig-list\">\n<li><strong>System Services</strong> (links angeordnet): Beinhaltet systemweite Dienste mit Bezug zur Kommunikation.</li>\n<li><strong>Communication Services</strong>: Umfasst die protokollunabhängigen und protokollspezifischen Kommunikationsdienste.</li>\n<li><strong>Communication Hardware Abstraction</strong>: Kapselt Hardwareeigenschaften der FlexRay-Controller.</li>\n<li><strong>Communication Drivers</strong>: Beinhaltet hardwarenahe Gerätetreiber.</li>\n<li><strong>µC / Hardware</strong>: Bildet die physischen Ausführungseinheiten (Mikrocontroller und externer Controller) ab.</li>\n</ul>\n<p class=\"fig-p\">Der Fokus liegt auf der Verortung des FlexRay Transportprotokolls (FrTp) innerhalb der Communication Services zwischen dem PDU Router und der Hardware-Abstraktionsschicht.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert folgende Module und Schichtbeziehungen:</p>\n<ul class=\"fig-list\">\n<li><strong>System Services</strong>: Enthält den <code>Ext. Time Service</code> (External Time Service).</li>\n<li><strong>Communication Services</strong>:</li>\n<li><code>Signal GW</code> (Signal Gateway)</li>\n<li><code>AUTOSAR COM</code></li>\n<li><code>DCM Diagnostic Com. Manager</code></li>\n<li><code>Generic NM</code> (Generic Network Management)</li>\n<li><code>XCP Transport Protocol on FlexRay</code> (durchgängig vertikal über die Communication Services angeordnet)</li>\n<li><code>PDU Router</code> (liegt unterhalb von <code>AUTOSAR COM</code> und <code>DCM Diagnostic Com. Manager</code>)</li>\n<li><code>FlexRay Transport Protocol</code> (FrTp, unterhalb des <code>PDU Router</code> platziert)</li>\n<li><code>FlexRay NM</code> (FlexRay Network Management, unterhalb von <code>Generic NM</code>)</li>\n<li><strong>Communication Hardware Abstraction</strong>:</li>\n<li><code>FlexRay Interface</code> (FrIf, bindet <code>PDU Router</code>, <code>FlexRay Transport Protocol</code>, <code>FlexRay NM</code> und <code>XCP Transport Protocol on FlexRay</code> nach unten an)</li>\n<li><code>Driver for external FlexRay Controller</code> (überspannt vertikal sowohl die Hardware-Abstraktions- als auch die Treiberschicht zur Anbindung eines externen Controllers)</li>\n<li><strong>Communication Drivers</strong>:</li>\n<li><code>Driver for internal FlexRay Controller</code> (hardwarenaher Treiber für On-Chip-Peripherie)</li>\n<li><strong>µC / Hardware Layer</strong>:</li>\n<li>Mikrocontroller (<code>µC</code>) mit integriertem <code>FlexRay</code>-Controller</li>\n<li><code>External FlexRay Controller</code> (außerhalb des µC angebunden über den externen Controller-Treiber)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm veranschaulicht statische Schichtenbeziehungen und Signal-/PDU-Datenflüsse:</p>\n<ul class=\"fig-list\">\n<li>Signale und Botschaften gelangen aus den oberen Ebenen über <code>AUTOSAR COM</code> oder <code>DCM</code> an den <code>PDU Router</code>.</li>\n<li>Unsegmentierte I-PDUs leitet der <code>PDU Router</code> direkt an das <code>FlexRay Interface</code> weiter.</li>\n<li>Zu segmentierende Datenpakete (I-PDUs größer als eine FlexRay-L-PDU) übergibt der <code>PDU Router</code> an das <code>FlexRay Transport Protocol</code> zur Segmentierung; in Empfangsrichtung erfolgt dort das Reassembly zur Übergabe an den <code>PDU Router</code>.</li>\n<li>Das <code>FlexRay Interface</code> bündelt die L-PDUs aus <code>PDU Router</code>, <code>FlexRay Transport Protocol</code>, <code>FlexRay NM</code> sowie <code>XCP Transport Protocol on FlexRay</code> und reicht sie an den <code>Driver for internal FlexRay Controller</code> bzw. den <code>Driver for external FlexRay Controller</code> weiter.</li>\n<li>Das Netzwerkmanagement interagiert über <code>Generic NM</code> und <code>FlexRay NM</code> mit dem <code>FlexRay Interface</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Entwickler und Integratoren des FlexRay Transport Protocol (FrTp) sind folgende Aspekte normativ relevant:</p>\n<ul class=\"fig-list\">\n<li><strong>Schnittstellen</strong>: FrTp muss die standardisierten oberen Schnittstellen zum <code>PDU Router</code> (PduR) sowie die unteren Schnittstellen zum <code>FlexRay Interface</code> (FrIf) implementieren.</li>\n<li><strong>Segmentierung / Reassembly</strong>: FrTp übernimmt ausschließlich den PDU-Transport größerer Nutzlasten; Standardnachrichten können das FrTp umgehen und direkt vom PDU Router zum FlexRay Interface fließen.</li>\n<li><strong>Hardware-Unabhängigkeit</strong>: FrTp interagiert niemals direkt mit den Controllertreibern (<code>Driver for internal FlexRay Controller</code> oder <code>Driver for external FlexRay Controller</code>), sondern ausschließlich abstrahiert über das <code>FlexRay Interface</code>.</li>\n<li><strong>Koexistenz</strong>: FrTp koexistiert in der Communication-Services-Schicht neben parallelen Pfaden wie <code>FlexRay NM</code> und <code>XCP Transport Protocol on FlexRay</code>.</li>\n</ul>"}, {"id": "FIG-7e6c1e55ee6cb9a7", "releases": ["R24-11", "R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Das Blockdiagramm zeigt die generalisierte AUTOSAR-Kommunikationsarchitektur (Classic Platform) zur Einbettung von protokollspezifischen Transport- und Schnittstellenmodulen. Es gliedert sich in zwei übergeordnete BSW-Schichten:</p>\n<ul class=\"fig-list\">\n<li><strong>Communication Services</strong>: Protokollübergreifende Routing-, Management- und Transportprotokoll-Services.</li>\n<li><strong>Communication Hardware Abstraction</strong>: Busunabhängige und busspezifische Abstraktionsmodule sowie Transceiver-Treiber.</li>\n</ul>\n<p class=\"fig-p\">Spezifische Bussysteme (wie CAN, FlexRay, LIN oder Ethernet) werden über parametrische Platzhaltermuster (<code>&lt;module&gt;</code>, <code>&lt;Ethernet&gt;</code>, <code>&lt;CAN, FlexRay, Lin&gt;</code>) repräsentiert. Treiberschichten und Hardware-Ebenen sind nicht dargestellt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm gliedert die Entitäten in zwei Schichten:</p>\n<ul class=\"fig-list\">\n<li><strong>Communication Services</strong>:</li>\n<li><code>AUTOSAR COM</code></li>\n<li><code>Diagnostic Com. Manager</code> (DCM)</li>\n<li><code>Debugging</code></li>\n<li><code>&lt;module&gt; State Manager</code></li>\n<li><code>Generic NM Interface</code></li>\n<li><code>&lt;module&gt; NM</code> (unterhalb von <code>Generic NM Interface</code>)</li>\n<li><code>IEEE1722Tp</code></li>\n<li>Sammelmodul: <code>IpduM, SecOC, Dds, SomeIpTp</code></li>\n<li><code>PDU Router</code> (L-förmig angeordnet um das Transportprotokoll)</li>\n<li><code>&lt;module&gt; Transport Protocol</code> (unterhalb des PDU Routers)</li>\n<li><strong>Communication Hardware Abstraction</strong>:</li>\n<li><code>L-SDU Router</code> (schichtenübergreifender Riegel oberhalb der Schnittstellen)</li>\n<li><code>&lt;Ethernet&gt; Interface</code></li>\n<li><code>Ethernet Transceiver Driver</code> (unterhalb des Ethernet-Interface)</li>\n<li><code>&lt;CAN, FlexRay, Lin&gt; Interface</code></li>\n<li><code>&lt;CAN, FlexRay,Lin&gt; Transceiver Driver</code> (innerhalb der Hardware-Abstraktionsschicht unterhalb der Bus-Interfaces)</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm stellt vertikale und horizontale Daten- sowie Steuerflüsse dar:</p>\n<ul class=\"fig-list\">\n<li>Nutzdaten und Diagnosedaten fließen von <code>AUTOSAR COM</code>, <code>Diagnostic Com. Manager</code>, <code>Debugging</code> oder dem Block <code>IpduM, SecOC, Dds, SomeIpTp</code> in den <code>PDU Router</code>.</li>\n<li>Der <code>PDU Router</code> leitet PDUs entweder direkt an die Hardware-Abstraktionsschicht weiter oder übergibt segmentierungsbedürftige PDUs an das busspezifische <code>&lt;module&gt; Transport Protocol</code>.</li>\n<li><code>IEEE1722Tp</code> fungiert als eigenständiges Transportprotokoll parallel zu den klassischen Services.</li>\n<li>In der <code>Communication Hardware Abstraction</code> vermittelt der <code>L-SDU Router</code> zwischen den oberen Schichten und den konkreten Bus-Interfaces (<code>&lt;Ethernet&gt; Interface</code> bzw. <code>&lt;CAN, FlexRay, Lin&gt; Interface</code>).</li>\n<li>Die Bus-Interfaces steuern die zugehörigen Transceiver (<code>Ethernet Transceiver Driver</code> bzw. <code>&lt;CAN, FlexRay,Lin&gt; Transceiver Driver</code>) an.</li>\n<li>Netzwerkzustände werden über <code>&lt;module&gt; State Manager</code> und das Zusammenspiel von <code>Generic NM Interface</code> und <code>&lt;module&gt; NM</code> koordiniert.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für Entwickler und Spezifikations-Integratoren ergeben sich folgende Vorgaben:</p>\n<ul class=\"fig-list\">\n<li><strong>Platzhalter-Spezifikation</strong>: <code>&lt;module&gt; Transport Protocol</code> repräsentiert busspezifische Implementierungen (z. B. FrTp, CanTp, LinTp) unter einer einheitlichen PDU-Router-Kopplung.</li>\n<li><strong>L-SDU Routing</strong>: Auf Hardware-Abstraktionsebene ist der <code>L-SDU Router</code> als Vermittlungsinstanz oberhalb der konkreten Interfaces (<code>&lt;CAN, FlexRay, Lin&gt; Interface</code>, <code>&lt;Ethernet&gt; Interface</code>) zu berücksichtigen.</li>\n<li><strong>Sicherheits- und Transformations-Pipeline</strong>: Durch Module wie <code>SecOC</code>, <code>SomeIpTp</code>, <code>IpduM</code> und <code>Dds</code> können PDUs vor dem Routing zusätzliche Verarbeitungsstufen durchlaufen.</li>\n<li><strong>Transceiver-Abstraktion</strong>: Transceiver-Treiber (<code>&lt;CAN, FlexRay,Lin&gt; Transceiver Driver</code>, <code>Ethernet Transceiver Driver</code>) sind integraler Bestandteil der Hardware-Abstraktionsschicht.</li>\n</ul>"}], "trans": [{"from": "FIG-9ea5d7b8790b654d", "to": "FIG-6a8393b5358e2932", "fr": "R4.0.3", "tr": "R4.1.3", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-6a8393b5358e2932", "to": "FIG-7e6c1e55ee6cb9a7", "fr": "R4.2.2", "tr": "R24-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Architekturansatz von technologiespezifischer FlexRay-Struktur auf einheitliches AUTOSAR-Kommunikationsschichten-Muster mit Platzhaltern (<code>&lt;module&gt;</code>, <code>&lt;Ethernet&gt;</code>, <code>&lt;CAN, FlexRay, Lin&gt;</code>) umgestellt.</li>\n<li>Schicht <code>System Services</code> (inklusive <code>Ext. Time Service</code>) vollständig entfernt.</li>\n<li>Schichten <code>Communication Drivers</code> und Microcontroller-Hardware (<code>µC</code>, interner FlexRay-Controller, <code>External FlexRay Controller</code>) vollständig aus dem Diagramm entfernt.</li>\n<li>In <code>Communication Services</code>:</li>\n<li><code>Signal GW</code> entfernt.</li>\n<li><code>Debugging</code>, <code>&lt;module&gt; State Manager</code> sowie ein Sammelblock für Protokoll- und Sicherheitsmodule (<code>IpduM, SecOC, Dds, SomeIpTp</code>) neu hinzugefügt.</li>\n<li><code>IEEE1722Tp</code> als eigenständiges Transportprotokoll ergänzt.</li>\n<li><code>Generic NM</code> durch <code>Generic NM Interface</code> ersetzt.</li>\n<li><code>FlexRay NM</code> zu <code>&lt;module&gt; NM</code> generalisiert.</li>\n<li><code>FlexRay Transport Protocol</code> zu <code>&lt;module&gt; Transport Protocol</code> generalisiert.</li>\n<li><code>XCP Transport Protocol on FlexRay</code> entfernt.</li>\n<li>In <code>Communication Hardware Abstraction</code>:</li>\n<li><code>L-SDU Router</code> als übergeordnete Abstraktionsschicht neu eingeführt.</li>\n<li><code>FlexRay Interface</code> durch getrennte Schnittstellenblöcke <code>&lt;Ethernet&gt; Interface</code> und <code>&lt;CAN, FlexRay, Lin&gt; Interface</code> ersetzt.</li>\n<li><code>Ethernet Transceiver Driver</code> und <code>&lt;CAN, FlexRay,Lin&gt; Transceiver Driver</code> neu integriert.</li>\n<li><code>Driver for external FlexRay Controller</code> entfernt.</li>\n</ul>"}]};
